mapper.select:


SELECT *
FROM (

) grouped_history
WHERE knownMembershipCount = 0 OR adminInGroup = 1
ORDER BY groupJid ASC
LIMIT #{offset}, #{pageSize}

SELECT phone.groupJid, phone.accountPhone, MAX(phone.currentRelation) AS currentRelation FROM ( SELECT baseline_group.group_jid AS groupJid, a.id AS accountId, a.ws_phone AS accountPhone, 0 AS currentRelation FROM account a INNER JOIN wa_account_group_binding baseline_binding ON baseline_binding.tenant_id = a.tenant_id AND baseline_binding.account_id = a.id AND baseline_binding.was_in_initial_baseline = 1 INNER JOIN wa_group baseline_group ON baseline_group.tenant_id = baseline_binding.tenant_id AND baseline_group.id = baseline_binding.group_id WHERE a.tenant_id = #{tenantId} AND a.account_group_id = #{accountGroupId} AND a.deleted_at IS NULL AND a.ws_phone IS NOT NULL AND TRIM(a.ws_phone) <> '' AND baseline_group.group_jid IN
#{groupJid}
UNION ALL SELECT current_group.group_jid AS groupJid, a.id AS accountId, a.ws_phone AS accountPhone, 1 AS currentRelation FROM wa_account_group_binding current_binding INNER JOIN account a ON a.tenant_id = current_binding.tenant_id AND a.id = current_binding.account_id INNER JOIN wa_group current_group ON current_group.tenant_id = current_binding.tenant_id AND current_group.id = current_binding.group_id INNER JOIN wa_group_participant self_participant ON self_participant.tenant_id = current_binding.tenant_id AND self_participant.group_id = current_binding.group_id AND self_participant.id = current_binding.participant_id AND self_participant.presence_status = 1 WHERE a.tenant_id = #{tenantId} AND a.account_group_id = #{accountGroupId} AND a.deleted_at IS NULL AND a.ws_phone IS NOT NULL AND TRIM(a.ws_phone) <> '' AND current_group.group_jid IN
#{groupJid}
) phone GROUP BY phone.groupJid, phone.accountPhone ORDER BY phone.groupJid ASC, MAX(phone.currentRelation) DESC, MIN(phone.accountId) ASC

SELECT a.id AS accountId, a.protocol_id AS protocolId, a.protocol_account_id AS protocolAccountId, a.ws_phone AS wsPhone, TRUE AS groupAdmin FROM group_link group_handle INNER JOIN account a ON a.tenant_id = group_handle.tenant_id AND (a.owner_user_id = group_handle.owner_user_id OR (a.owner_user_id IS NULL AND group_handle.owner_user_id IS NULL)) AND a.deleted_at IS NULL AND a.protocol_account_id IS NOT NULL AND a.protocol_account_id != '' AND a.ws_phone IS NOT NULL AND a.ws_phone != '' INNER JOIN account_state s ON s.tenant_id = a.tenant_id AND s.account_id = a.id AND s.login_state = #{onlineLoginState} AND s.account_state IN #{executableState} LEFT JOIN wa_account_group_binding binding ON binding.tenant_id = group_handle.tenant_id AND binding.group_id = group_handle.group_id AND binding.account_id = a.id LEFT JOIN wa_group_participant self_participant ON self_participant.tenant_id = binding.tenant_id AND self_participant.group_id = binding.group_id AND self_participant.id = binding.participant_id AND self_participant.presence_status = 1 WHERE group_handle.id = #{groupLinkId} AND group_handle.deleted_at IS NULL AND a.ws_phone IN
#{phone}
ORDER BY COALESCE( CASE WHEN self_participant.id IS NOT NULL THEN binding.last_observed_at END, 0 ) DESC, a.id ASC LIMIT #{limit}
